import csv


def load(path):
    f = open(path, encoding="utf-8")
    rows = list(csv.reader(f))
    return rows


def clean(rows):
    seen = set()
    out = []
    for i in range(len(rows)):
        name = rows[i][0].strip()
        if name not in seen:
            seen.add(name)
            out.append(name)
    len(out)
    def is_empty(s):
        return s == ""
    if type(out) == list:
        return [n for n in out if not is_empty(n)]

